 public const string Folder="TruckDanceOff",Scene="Assets/TruckDanceOff/Scenes/TruckDanceOff.unity",LibraryPath="Assets/TruckDanceOff/Audio/Original Dance Library.asset";
 [Serializable]sealed class Source {public DanceSongLibrary.Song[] songs;}
 static Material navy,steel,ivory,pink,cyan;static DanceMatch match;
 public static DanceSongLibrary EnsureLibrary(){var lib=AssetDatabase.LoadAssetAtPath<DanceSongLibrary>(LibraryPath);if(lib!=null){lib.Validate();return lib;}lib=ScriptableObject.CreateInstance<DanceSongLibrary>();lib.songs=JsonUtility.FromJson<Source>(File.ReadAllText("Assets/TruckDanceOff/Audio/Music/Original Beat Charts.json")).songs;foreach(var s in lib.songs){string path="Assets/TruckDanceOff/Audio/Music/"+s.title+".wav";var importer=(AudioImporter)AssetImporter.GetAtPath(path);var settings=importer.defaultSampleSettings;settings.loadType=AudioClipLoadType.Streaming;settings.compressionFormat=AudioCompressionFormat.Vorbis;settings.quality=.85f;settings.sampleRateSetting=AudioSampleRateSetting.PreserveSampleRate;importer.defaultSampleSettings=settings;importer.forceToMono=false;importer.SaveAndReimport();s.music=AssetDatabase.LoadAssetAtPath<AudioClip>(path);}lib.Validate();AssetDatabase.CreateAsset(lib,LibraryPath);return lib;}
 [MenuItem("Truck Sports/Dance-Off/Create new nightclub scene")]
 public static void Create(){if(File.Exists(Scene))throw new InvalidOperationException("The hand-edited Dance-Off scene already exists. Use a targeted upgrade.");match=SportsEventAuthoring.Begin<DanceMatch>(Folder);match.option=7;match.setup.count=4;match.NormalizeSetup();match.library=EnsureLibrary();for(int i=1;i<match.setup.players.Length;i++)match.setup.players[i].source=LWS.TruckBowling.BowlingSource.AI;
  navy=Mat("Midnight enamel",new Color(.014f,.018f,.042f),.58f);steel=Mat("Brushed touring truss",new Color(.12f,.15f,.2f),.5f);steel.SetFloat("_Metallic",.8f);ivory=Mat("Warm ivory",new Color(.96f,.92f,.79f),.3f);pink=Glow("Laser pink",new Color(1,.05f,.4f));cyan=Glow("Electric cyan",new Color(.03f,.8f,1));
  RenderSettings.ambientLight=new Color(.065f,.065f,.14f);RenderSettings.fog=true;RenderSettings.fogColor=new Color(.025f,.018f,.065f);RenderSettings.fogDensity=.008f;var sun=UnityEngine.Object.FindAnyObjectByType<Light>();sun.intensity=.2f;
  var ground=SportsEventAuthoring.Contact(Folder,"Club stage physical deck",.7f,.05f);SportsEventAuthoring.Box("Polished nightclub floor",new Vector3(0,-.4f,1),new Vector3(55,.5f,42),navy,ground);SportsEventAuthoring.Box("Acoustic back wall",new Vector3(0,7,17),new Vector3(55,15,.4f),navy,ground);
  match.dancers=new DanceTruckRig[4];for(int i=0;i<4;i++){float x=(i-1.5f)*10;var deck=Cylinder("Machined octagonal dance deck "+(i+1),new Vector3(x,.1f,0),new Vector3(8,.6f,8),navy);deck.GetComponent<Collider>().sharedMaterial=ground;var rim=Cylinder("Luminous stage perimeter",new Vector3(x,.47f,0),new Vector3(8.15f,.07f,8.15f),i%2==0?pink:cyan);UnityEngine.Object.DestroyImmediate(rim.GetComponent<Collider>());
   var truck=SportsEventAuthoring.Truck(match,Folder,"Dancer "+(i+1),new Vector3(x,1.12f,0),i);SportsRallyAuthoring.FitTruck(truck);var d=truck.gameObject.AddComponent<DanceTruckRig>();d.truck=truck;d.deck=deck.transform;var lamp=new GameObject("Colored stage spotlight").AddComponent<Light>();lamp.type=LightType.Spot;lamp.range=28;lamp.spotAngle=48;lamp.intensity=4;lamp.transform.position=new Vector3(x,13,-3);lamp.transform.LookAt(new Vector3(x,0,0));lamp.color=match.setup.players[i].color;lamp.shadows=LightShadows.None;d.accent=lamp;match.dancers[i]=d;
   for(int bar=0;bar<8;bar++){var p=new Vector3(x-3.5f+bar, .55f,3.25f);SportsEventAuthoring.Box("Inset LED beat segment",p,new Vector3(.7f,.06f,.16f),bar%2==0?cyan:pink);}
  }
  // Purpose-modeled touring stacks and truss. Installed asset-name audit found
  // no speaker/nightclub/DJ mesh; no vendor audio or animation is reinvented.
  for(int side=-1;side<=1;side+=2){for(int row=0;row<3;row++){var p=new Vector3(side*22,1.7f+row*3,7);SportsEventAuthoring.Box("Touring speaker cabinet",p,new Vector3(3.4f,2.8f,1.8f),steel);for(int k=-1;k<=1;k+=2){var cone=Cylinder("Recessed speaker cone",p+new Vector3(0,k*.65f,-.95f),new Vector3(1.15f,.12f,1.15f),navy);cone.transform.rotation=Quaternion.Euler(90,0,0);UnityEngine.Object.DestroyImmediate(cone.GetComponent<Collider>());}}for(int y=0;y<8;y++){SportsEventAuthoring.Box("Touring truss diagonal",new Vector3(side*24,y*1.6f,11),new Vector3(.14f,2.1f,.14f),steel).transform.rotation=Quaternion.Euler(0,0,y%2==0?40:-40);}}
  for(int i=0;i<28;i++){float height=2+Mathf.Sin(i*.73f)*1.5f;SportsEventAuthoring.Box("Rear LED equalizer column",new Vector3((i-13.5f)*1.2f,3+height*.5f,16.7f),new Vector3(.7f,height,.08f),i%3==0?pink:cyan);}
  var logo=SportsEventAuthoring.Label("Stage title","DIESEL DISCOTHEQUE",new Vector3(0,10,16.2f),.32f,ivory.color);logo.transform.rotation=Quaternion.Euler(0,180,0);
  var camera=SportsEventAuthoring.Camera("Dance-Off broadcast");camera.Pose(new Vector3(0,3,1),new Vector3(0,20,-32),58,true);camera.view.farClipPlane=200;match.stageCamera=camera.view;match.cameras=new[]{camera.view};
  match.music=match.gameObject.AddComponent<AudioSource>();match.music.playOnAwake=false;match.music.loop=false;match.music.spatialBlend=0;match.music.priority=20;match.calibrationAudio=match.gameObject.AddComponent<AudioSource>();match.calibrationAudio.playOnAwake=false;match.calibrationAudio.clip=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/TruckDanceOff/Audio/Calibration pulse.wav");match.calibrationAudio.spatialBlend=0;match.feedback.clips=(AudioClip[])LWS.TruckHockey.Editor.HockeyAudioAuthoring.Create().Clone();
  SportsEventAuthoring.UI(match);SportsRallyAuthoring.CompactUI(match);var setup=match.menus.pages[0].transform;match.formatChoice=SportsUIAuthoring.Button(setup,"SINGLE SONG","dance-format",new Vector2(-340,-260),new Vector2(540,44)).normalTextObj;match.calibrationText=SportsUIAuthoring.Text("Saved timing offset",setup,"",new Vector2(380,44),new Vector2(330,-260),22);SportsUIAuthoring.Button(setup,"âˆ’","dance-offset-",new Vector2(80,-260),new Vector2(80,44));SportsUIAuthoring.Button(setup,"+","dance-offset+",new Vector2(580,-260),new Vector2(80,44));
  SportsUIAuthoring.Button(setup,"TAP CALIBRATION","dance-calibrate",new Vector2(0,-318),new Vector2(500,40));RhythmHUD();DanceVenueAuthoring.Install(match);SportsBroadcastAuthoring.ApplyScene();DancePresentationAuthoring.Install(match);SportsEventAuthoring.Save(Folder);Validate();
 }
 static void RhythmHUD(){var root=SportsUIAuthoring.Rect("Rhythm lanes",match.menus.hud.transform,new Vector2(1920,1080),Vector2.zero);var hud=root.AddComponent<DanceHud>();hud.surface=root;match.rhythmHud=hud;hud.song=SportsUIAuthoring.Text("Music title",root.transform,"",new Vector2(1450,60),new Vector2(0,450),32);hud.time=SportsUIAuthoring.Text("Rhythm status",root.transform,"",new Vector2(1450,44),new Vector2(0,390),24);hud.progress=SportsUIAuthoring.Rect("Song progress",root.transform,new Vector2(1450,5),new Vector2(-725,355)).GetComponent<RectTransform>();hud.progress.pivot=new Vector2(0,.5f);hud.progress.gameObject.AddComponent<Image>().color=new Color(.13f,.9f,.8f);hud.strips=new DanceHud.Strip[4];for(int i=0;i<4;i++){var s=new DanceHud.Strip();hud.strips[i]=s;s.root=SportsUIAuthoring.Rect("Owned chart "+i,root.transform,new Vector2(340,650),Vector2.zero).GetComponent<RectTransform>();s.root.gameObject.AddComponent<Image>().color=new Color(.008f,.014f,.035f,.82f);s.group=s.root.gameObject.AddComponent<CanvasGroup>();s.title=SportsUIAuthoring.Text("Player",s.root,"",new Vector2(320,42),new Vector2(0,285),24);s.judgment=SportsUIAuthoring.Text("Judgment",s.root,"FEEL THE BEAT",new Vector2(320,45),new Vector2(0,-265),26);s.combo=SportsUIAuthoring.Text("Points combo",s.root,"",new Vector2(320,45),new Vector2(0,235),27);s.routine=SportsUIAuthoring.Text("Truck move",s.root,"",new Vector2(320,32),new Vector2(0,-305),18);s.controls=SportsUIAuthoring.Text("Owned lane prompts",s.root,"",new Vector2(320,30),new Vector2(0,-225),18);var field=SportsUIAuthoring.Rect("Clipped note field",s.root,new Vector2(310,420),Vector2.zero).GetComponent<RectTransform>();field.gameObject.AddComponent<RectMask2D>();s.receptors=new Image[4];for(int lane=0;lane<4;lane++){float x=(lane-1.5f)*68;var rail=SportsUIAuthoring.Rect("Lane "+lane,field,new Vector2(2,405),new Vector2(x,-10));rail.AddComponent<Image>().color=new Color(.4f,.5f,.7f,.15f);var rec=SportsUIAuthoring.Rect("Receptor "+lane,field,new Vector2(38,38),new Vector2(x,-190));rec.transform.localRotation=Quaternion.Euler(0,0,45);s.receptors[lane]=rec.AddComponent<Image>();}
   s.notes=new RectTransform[48];s.tails=new RectTransform[48];s.faces=new Image[48];s.tailFaces=new Image[48];for(int n=0;n<48;n++){s.tails[n]=SportsUIAuthoring.Rect("Hold tail "+n,field,new Vector2(12,30),Vector2.zero).GetComponent<RectTransform>();s.tailFaces[n]=s.tails[n].gameObject.AddComponent<Image>();s.notes[n]=SportsUIAuthoring.Rect("Pooled note "+n,field,new Vector2(32,32),Vector2.zero).GetComponent<RectTransform>();s.notes[n].localRotation=Quaternion.Euler(0,0,45);s.faces[n]=s.notes[n].gameObject.AddComponent<Image>();s.notes[n].gameObject.SetActive(false);s.tails[n].gameObject.SetActive(false);}
  }root.SetActive(false);match.menus.header.transform.parent.gameObject.SetActive(false);}
 static Material Mat(string name,Color color,float smooth)=>SportsEventAuthoring.Mat(Folder,name,color,smooth);
 static Material Glow(string name,Color color){var m=Mat(name,color,.5f);m.EnableKeyword("_EMISSION");m.SetColor("_EmissionColor",color*2);return m;}
 static GameObject Cylinder(string name,Vector3 p,Vector3 size,Material mat){var g=GameObject.CreatePrimitive(PrimitiveType.Cylinder);g.name=name;g.transform.position=p;g.transform.localScale=new Vector3(size.x,size.y*.5f,size.z);g.GetComponent<Renderer>().sharedMaterial=mat;return g;}
 public static void Validate(){var m=UnityEngine.Object.FindAnyObjectByType<DanceMatch>();if(m==null||m.dancers.Length!=4||m.rhythmHud==null||m.rhythmHud.strips.Length!=4||m.cameras.Length!=1||m.music==null)throw new InvalidOperationException("Dance-Off saved scene references are incomplete.");m.library.Validate();if(UnityEngine.Object.FindObjectsByType<AudioListener>(FindObjectsInactive.Include).Length!=1)throw new InvalidOperationException("Dance-Off requires one listener.");Debug.Log("DANCE_OFF_SAVED_VALIDATED seven songs / 28 charts / four owned platforms.");}
}
